function countOperations(num1, num2) {
  // Euclid-style shortcut: every run of identical subtractions is counted with one division.
  let a = Math.max(num1, num2), b = Math.min(num1, num2), count = 0;
  while (b > 0) {
    count += Math.floor(a / b);
    const rest = a % b;
    a = b;
    b = rest;
  }
  return count;
}

