function generate(rand, size) {
  const limit = size === 'large' ? 100000 : 30;
  const pick = () => {
    const roll = rand();
    if (roll < 0.08) return 0;
    if (roll < 0.16) return 1;
    if (roll < 0.24) return limit;
    return Math.floor(rand() * (limit + 1));
  };
  const num1 = pick();
  const num2 = rand() < 0.1 ? num1 : pick();
  return [num1, num2];
}
